\begin{document}
\title{Universal correlations in

chaotic many-body quantum states: \\ Fock-space formulation of Berry's random wave model}

\author{Florian Schoeppl}
\affiliation{Institut f\"ur Theoretische Physik, Universit\"at Regensburg, 93040 Regensburg, Germany}
\author{R\'emy~Dubertrand}
\affiliation{Department of Mathematics, Physics and Electrical Engineering, Northumbria University, NE1 8ST Newcastle upon Tyne, United Kingdom}
